// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v, uint _decimals) public {
        vm.assume(_tos.length > 0);
        // Bound v and _decimals to avoid overflow
        v = bound(v, 0, 1e10);
        _decimals = bound(_decimals, 0, 18);
        // Try to call transfer and catch revert
        try c.transfer(from, caddress, _tos, v, _decimals) returns (bool result) {
            assertTrue(result == true);
        } catch {
            // revert is acceptable
        }
    }
}

